package dev.starcrownqa;
import dev.starcrown.*;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.effect.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.*;
import net.minecraft.core.Direction;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.common.MinecraftForge;
@GameTestHolder("starcrownqa") @PrefixGameTestTemplate(false)
public final class DiligenceTests {
 @GameTest(template="empty",timeoutTicks=100) public static void idleAndActivity(GameTestHelper h){var p=ChastityTests.player(h);try{ChastityTests.equip(p);for(int i=0;i<60;i++)YuleDiligence.tickPlayer(p);h.assertTrue(!p.hasEffect(MobEffects.WITHER),"no penalty through three seconds");YuleDiligence.tickPlayer(p);h.assertTrue(p.hasEffect(MobEffects.WITHER)&&p.getEffect(MobEffects.WITHER).getAmplifier()==2,"Wither III after3 seconds");YuleChastity.tick(new net.minecraftforge.event.TickEvent.PlayerTickEvent(net.minecraftforge.event.TickEvent.Phase.START,p));h.assertTrue(p.hasEffect(MobEffects.WITHER),"Chastity does not erase owned penalty");try{var field=net.minecraft.server.level.ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");field.setAccessible(true);field.setInt(p,0);}catch(ReflectiveOperationException ex){throw new RuntimeException(ex);}float health=p.getHealth();MobEffects.WITHER.applyEffectTick(p,2);h.assertTrue(p.getHealth()<health,"Wither penalty actually damages player");p.swinging=true;YuleDiligence.tickPlayer(p);h.assertTrue(!p.hasEffect(MobEffects.WITHER)&&p.getEffect(MobEffects.DIG_SPEED).getAmplifier()==9&&p.getEffect(MobEffects.MOVEMENT_SPEED).getAmplifier()==2,"working clears penalty and grantsHasteX SpeedIII");h.assertTrue(YuleDiligence.units(p)==0,"swinging alone earns no XP or growth");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);YuleDiligence.tickPlayer(p);h.assertTrue(!p.hasEffect(MobEffects.WITHER)&&!p.hasEffect(MobEffects.DIG_SPEED)&&!p.hasEffect(MobEffects.MOVEMENT_SPEED),"unequip clears own effects");ChastityTests.equip(p);h.assertTrue(!p.addEffect(new MobEffectInstance(MobEffects.WITHER,1000,2)),"ordinary hostile Wither remains immune");h.succeed();}finally{ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void movementGrowthAndPersistence(GameTestHelper h){var p=ChastityTests.player(h);var clone=ChastityTests.player(h);try{ChastityTests.equip(p);YuleDiligence.tickPlayer(p);var start=p.position();p.setPos(start.x+1.25,start.y,start.z);YuleDiligence.tickPlayer(p);h.assertTrue(YuleDiligence.units(p)==1&&p.totalExperience==1000,"one actual block gives one reward");h.assertTrue(Math.abs(p.getMaxHealth()-20.1)<.001&&Math.abs(p.getLuck()-.01)<.001,"health and luck growth applied");p.setPos(start.x+101.25,start.y,start.z);YuleDiligence.tickPlayer(p);h.assertTrue(YuleDiligence.units(p)==1,"teleport does not reward steps");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);YuleDiligence.tickPlayer(p);h.assertTrue(p.getMaxHealth()>20&&p.getLuck()>0,"growth persists after unequip");p.getPersistentData().putLong(YuleDiligence.COUNT,200000);YuleDiligence.refresh(p);h.assertTrue(p.getMaxHealth()>20000&&p.getLuck()>1900,"growth exceeds vanilla1024 attribute caps");var tag=new net.minecraft.nbt.CompoundTag();p.saveWithoutId(tag);h.assertTrue(tag.getCompound("ForgeData").getLong(YuleDiligence.COUNT)==200000,"growth saved to player data");YuleDiligence.clone(new net.minecraftforge.event.entity.player.PlayerEvent.Clone(clone,p,true));h.assertTrue(YuleDiligence.units(clone)==200000&&clone.getMaxHealth()>20000,"death clone retains permanent growth");h.succeed();}finally{ChastityTests.close(p);ChastityTests.close(clone);}}
 @GameTest(template="empty",timeoutTicks=100) public static void bedsAndSpawn(GameTestHelper h){var p=ChastityTests.player(h);var bed=p.blockPosition().offset(2,0,0);var original=bed.offset(5,0,0);var level=p.serverLevel();try{level.setBlockAndUpdate(bed,Blocks.RED_BED.defaultBlockState());p.setRespawnPosition(level.dimension(),original,0,true,false);ChastityTests.equip(p);h.assertTrue(p.startSleepInBed(bed).left().isPresent(),"bed sleeping rejected");p.startSleeping(bed);h.assertTrue(!p.isSleeping(),"direct forced bed sleep rejected");p.setRespawnPosition(level.dimension(),bed,0,false,false);h.assertTrue(original.equals(p.getRespawnPosition()),"bed cannot overwrite respawn");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);p.setRespawnPosition(level.dimension(),bed,0,false,false);h.assertTrue(bed.equals(p.getRespawnPosition()),"unequip restores bed spawn");h.succeed();}finally{level.setBlockAndUpdate(bed,Blocks.AIR.defaultBlockState());ChastityTests.close(p);}}
 static void click(net.minecraft.server.level.ServerPlayer p,net.minecraft.core.BlockPos pos){MinecraftForge.EVENT_BUS.post(new PlayerInteractEvent.LeftClickBlock(p,pos,Direction.UP,PlayerInteractEvent.LeftClickBlock.Action.START));}
 @GameTest(template="empty",timeoutTicks=100) public static void instantMiningAndPlacement(GameTestHelper h){var p=ChastityTests.player(h);var pos=p.blockPosition().offset(2,0,0);var level=p.serverLevel();try{ChastityTests.equip(p);level.setBlockAndUpdate(pos,Blocks.OBSIDIAN.defaultBlockState());click(p,pos);h.assertTrue(level.getBlockState(pos).isAir(),"obsidian instantly breaks on actual left-click event");for(int i=0;i<10;i++){level.setBlockAndUpdate(pos,Blocks.BEDROCK.defaultBlockState());click(p,pos);h.assertTrue(level.getBlockState(pos).isAir(),"bedrock instant breaks "+i);}h.assertTrue(YuleDiligence.units(p)==11&&p.totalExperience==11000,"one reward per actual break");level.setBlockAndUpdate(pos,Blocks.BEDROCK.defaultBlockState());click(p,pos);h.assertTrue(level.getBlockState(pos).is(Blocks.BEDROCK)&&YuleDiligence.units(p)==11,"Temperance eleventh break blocked without XP");var stack=new ItemStack(Items.COBBLESTONE,4);p.setItemInHand(InteractionHand.MAIN_HAND,stack);level.setBlockAndUpdate(pos.above(),Blocks.AIR.defaultBlockState());var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos).add(0,.5,0),Direction.UP,pos,false);stack.useOn(new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,hit));YuleDiligence.flush(p);h.assertTrue(level.getBlockState(pos.above()).is(Blocks.COBBLESTONE)&&YuleDiligence.units(p)==12,"successful placement rewards exactly once");h.assertTrue(stack.getCount()==4,"Temperance building remains free");h.succeed();}finally{level.setBlockAndUpdate(pos.above(),Blocks.AIR.defaultBlockState());level.setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void luckAndExistingEffects(GameTestHelper h){var p=ChastityTests.player(h);try{ChastityTests.equip(p);p.getPersistentData().putLong(YuleDiligence.COUNT,10000);YuleDiligence.refresh(p);var book=new ItemStack(Items.ENCHANTED_BOOK);EnchantedBookItem.addEnchantment(book,new EnchantmentInstance(Enchantments.BLOCK_EFFICIENCY,1));var result=YuleDiligence.improveGifts(java.util.List.of(book),p,true);h.assertTrue(EnchantmentHelper.getEnchantments(result.get(0)).get(Enchantments.BLOCK_EFFICIENCY)==5,"luck improves village book to registered enchantment max");h.assertTrue(EnchantmentHelper.getEnchantments(book).get(Enchantments.BLOCK_EFFICIENCY)==1,"trade source stays unchanged");p.getRandom().setSeed(12345);int count=0;for(int i=0;i<100;i++)count+=YuleDiligence.improveGifts(java.util.List.of(new ItemStack(Items.LEATHER)),p,false).size();h.assertTrue(count>100,"luck gives extra animal gift rolls");p.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED,500,0));p.swinging=true;YuleDiligence.tickPlayer(p);h.assertTrue(p.getEffect(MobEffects.MOVEMENT_SPEED).getAmplifier()==2,"activity upgrades existing weaker speed");p.swinging=false;YuleDiligence.state(p).workUntil=Long.MIN_VALUE;YuleDiligence.tickPlayer(p);h.assertTrue(p.getEffect(MobEffects.MOVEMENT_SPEED)!=null&&p.getEffect(MobEffects.MOVEMENT_SPEED).getAmplifier()==0,"stopping restores prior speed effect");h.succeed();}finally{ChastityTests.close(p);}}
 public static final class Deny {final java.util.UUID owner;Deny(java.util.UUID id){owner=id;}@net.minecraftforge.eventbus.api.SubscribeEvent(priority=net.minecraftforge.eventbus.api.EventPriority.HIGHEST) public void breaking(net.minecraftforge.event.level.BlockEvent.BreakEvent e){if(e.getPlayer().getUUID().equals(owner))e.setCanceled(true);}@net.minecraftforge.eventbus.api.SubscribeEvent(priority=net.minecraftforge.eventbus.api.EventPriority.LOWEST) public void placed(net.minecraftforge.event.level.BlockEvent.EntityPlaceEvent e){if(e.getEntity()!=null&&e.getEntity().getUUID().equals(owner))e.setCanceled(true);}}
 @GameTest(template="empty",timeoutTicks=100) public static void canceledWorkNoReward(GameTestHelper h){var p=ChastityTests.player(h);var pos=p.blockPosition().offset(2,0,0);var level=p.serverLevel();var deny=new Deny(p.getUUID());try{ChastityTests.equip(p);MinecraftForge.EVENT_BUS.register(deny);level.setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());click(p,pos);h.assertTrue(level.getBlockState(pos).is(Blocks.STONE)&&YuleDiligence.units(p)==0,"canceled mining gives no growth");var stack=new ItemStack(Items.COBBLESTONE,4);p.setItemInHand(InteractionHand.MAIN_HAND,stack);level.setBlockAndUpdate(pos.above(),Blocks.AIR.defaultBlockState());var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos).add(0,.5,0),Direction.UP,pos,false);stack.useOn(new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,hit));YuleDiligence.flush(p);h.assertTrue(level.getBlockState(pos.above()).isAir()&&YuleDiligence.units(p)==0&&p.totalExperience==0,"late canceled placement rolls back without reward");h.succeed();}finally{MinecraftForge.EVENT_BUS.unregister(deny);level.setBlockAndUpdate(pos.above(),Blocks.AIR.defaultBlockState());level.setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());ChastityTests.close(p);}}
}
